"""Раздел 6. Зоны оптимального использования электротрактора; заключение."""
import numpy as np

from repdata import FIG, f, pc


def org_threshold(D, impl, l):
    g = D.zo[(D.zo.implement == impl) & np.isclose(D.zo.l_km, l)]
    neg = g[g.I < 0]
    return neg.S_task.min() if len(neg) else np.nan


def econ_threshold(D, impl, Ty):
    g = D.ze[(D.ze.implement == impl) & np.isclose(D.ze.T_year, Ty)].sort_values("c_D")
    pos = g[g.dC_tot < 0]
    return pos.c_D.min() if len(pos) else np.nan


def amax(D, impl, v, col):
    g = D.zt[(D.zt.implement == impl)]
    vv = g.v.unique()[np.argmin(abs(g.v.unique() - v))]
    gg = g[np.isclose(g.v, vv) & g[col]]
    return gg.a.max()


def build(doc, D):
    P = D.P
    doc.h1(6, "Зоны оптимального использования электротрактора")

    doc.h2("6.1", "Понятие и критерии зоны оптимального использования")
