    doc.fig(FIG / "f24_zone_tech_S1.png", "Технологическая зона и интегральный индекс в сценарии 1 (полная загрузка в течение смены)")
    doc.fig(FIG / "f24_zone_tech_S2.png", "Технологическая зона и интегральный индекс в сценарии 2 (сменное задание 0,5 га)")
